class Solution:
    def maxRequests(self, timestamps: list[int], window: int) -> int:
        timestamps.sort()
        l = r = 0
        best = 0
        while r < len(timestamps):
            while timestamps[r] - timestamps[l] > window:
                l += 1
            best = max(best, r - l + 1)
            r += 1
        return best
